def remove(self, name: str) -> None:
    self._snapshots.pop(name, None)

def drain(self, name: str, reason: str) -> WorkerSnapshot:
    snapshot = self.get(name).drain(reason)
    self._snapshots[name] = snapshot
    return snapshot

def resume(self, name: str) -> WorkerSnapshot:
    snapshot = self.get(name).resume()
    self._snapshots[name] = snapshot
    return snapshot

def list_workers(registry: WorkerRegistry, *, queue: str | None = None, now: datetime | None = None) -> str:
    return render_worker_table(registry.list(queue=queue), now=now)


def drain_worker(registry: WorkerRegistry, name: str, reason: str) -> str:
    registry.drain(name, reason)
    return f"Draining {name}: {reason}"


def resume_worker(registry: WorkerRegistry, name: str) -> str:
    registry.resume(name)
    return f"Resumed {name}"

